const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define coastal region of Victoria and New South Wales
  const coastalRegion = ee.Geometry.Polygon([
    [140.0, -39.0], [155.0, -39.0], [155.0, -33.0], [140.0, -33.0], [140.0, -39.0]
  ]);

  // 2. Define dates for comparison
  const date1 = '2019-07-24';
  const date2 = '2020-01-01';

  // 3. Get MODIS Aerosol Optical Depth data (smoke indicator)
  const getAODData = function(date) {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    return ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
      .filterDate(startDate, endDate)
      .filterBounds(coastalRegion)
      .select('Optical_Depth_055');
  };

  // 4. Get data for both dates
  const col1 = getAODData(date1);
  const col2 = getAODData(date2);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`${date1} Images: ${size1}`);
  console.log(`${date2} Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Process images - use mean composite for each date
  const img1 = col1.mean().multiply(0.001); // Scale factor
  const img2 = col2.mean().multiply(0.001); // Scale factor

  // 6. Calculate mean AOD values
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = img1.reduceRegion({
    reducer: reducer,
    geometry: coastalRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: reducer,
    geometry: coastalRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('Optical_Depth_055_mean').getInfo();
  const count1 = stats1.get('Optical_Depth_055_count').getInfo();
  const mean2 = stats2.get('Optical_Depth_055_mean').getInfo();
  const count2 = stats2.get('Optical_Depth_055_count').getInfo();

  console.log(`${date1} Mean AOD: ${mean1?.toFixed(4)}, Pixels: ${count1}`);
  console.log(`${date2} Mean AOD: ${mean2?.toFixed(4)}, Pixels: ${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare smoke levels (AOD values)
  const moreSmokeOnJan2020 = mean2 > mean1;

  console.log(`AOD Difference: ${(mean2 - mean1).toFixed(4)}`);

  if (moreSmokeOnJan2020) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
